"""
In-memory indexes over all loaded techniques. O(1) lookups.
"""

from typing import Dict, List, Optional, Union

from .constants import V19_REVOCATION_MAP
from .loader import ATTACKLoader
from .models import Domain, SubTechnique, Tactic, Technique

TechniqueOrSub = Union[Technique, SubTechnique]


def normalize_attack_id(attack_id: str) -> str:
    return attack_id.strip().replace("/", ".")


def _phase_key(tactic: Tactic) -> str:
    return tactic.name.lower().replace(" ", "-")


class ATTACKIndex:
    def __init__(self, loader: ATTACKLoader):
        self._by_id: Dict[str, TechniqueOrSub] = {}
        self._by_domain_id: Dict[tuple[Domain, str], TechniqueOrSub] = {}
        self._by_tactic: Dict[str, List[str]] = {}
        self._by_platform: Dict[str, List[str]] = {}
        self._subtechniques_by_parent: Dict[tuple[Domain, str], List[str]] = {}
        self._tactics: Dict[str, Tactic] = {}
        self._phase_to_tactic: Dict[str, str] = {}
        self._phase_to_tactic_by_domain: Dict[tuple[Domain, str], str] = {}

        for domain in Domain:
            for tactic in loader.get_tactics(domain):
                self._tactics[tactic.attack_id] = tactic
                phase_key = _phase_key(tactic)
                self._phase_to_tactic.setdefault(phase_key, tactic.attack_id)
                self._phase_to_tactic_by_domain[(domain, phase_key)] = tactic.attack_id

            for technique in loader.get_techniques(domain):
                self._by_domain_id[(domain, technique.attack_id)] = technique
                self._by_id.setdefault(technique.attack_id, technique)
                for phase_name in technique.tactic_ids:
                    tactic_id = self.tactic_id_for_phase(phase_name, domain)
                    self._by_tactic.setdefault(tactic_id, []).append(technique.attack_id)
                for platform in technique.platforms:
                    self._by_platform.setdefault(platform.lower(), []).append(technique.attack_id)

            for subtechnique in loader.get_subtechniques(domain):
                self._by_domain_id[(domain, subtechnique.attack_id)] = subtechnique
                self._by_id.setdefault(subtechnique.attack_id, subtechnique)
                self._subtechniques_by_parent.setdefault(
                    (domain, subtechnique.parent_id), []
                ).append(subtechnique.attack_id)
                for phase_name in subtechnique.tactic_ids:
                    tactic_id = self.tactic_id_for_phase(phase_name, domain)
                    self._by_tactic.setdefault(tactic_id, []).append(subtechnique.attack_id)
                for platform in subtechnique.platforms:
                    self._by_platform.setdefault(platform.lower(), []).append(
                        subtechnique.attack_id
                    )

    def resolve_attack_id(self, attack_id: str) -> str:
        normalized_id = normalize_attack_id(attack_id)
        return V19_REVOCATION_MAP.get(normalized_id, normalized_id)

    def get(self, attack_id: str, domain: Domain | None = None) -> Optional[TechniqueOrSub]:
        resolved_id = self.resolve_attack_id(attack_id)
        if domain is not None:
            return self._by_domain_id.get((domain, resolved_id))
        return self._by_id.get(resolved_id)

    def get_exact(self, attack_id: str, domain: Domain | None = None) -> Optional[TechniqueOrSub]:
        normalized_id = normalize_attack_id(attack_id)
        if domain is not None:
            return self._by_domain_id.get((domain, normalized_id))
        return self._by_id.get(normalized_id)

    def tactic_id_for_phase(self, phase_name: str, domain: Domain | None = None) -> str:
        if phase_name in self._tactics:
            return phase_name
        if domain is not None:
            return self._phase_to_tactic_by_domain.get((domain, phase_name), phase_name)
        return self._phase_to_tactic.get(phase_name, phase_name)

    def tactic_for_technique(self, technique: TechniqueOrSub) -> Optional[Tactic]:
        if not technique.tactic_ids:
            return None
        return self._tactics.get(
            self.tactic_id_for_phase(technique.tactic_ids[0], technique.domain)
        )

    def parent_for(self, technique: TechniqueOrSub) -> Optional[TechniqueOrSub]:
        if not technique.is_subtechnique:
            return technique
        return self.get_exact(technique.parent_id, technique.domain)

    def by_tactic(self, tactic_id: str) -> List[TechniqueOrSub]:
        resolved_tactic_id = self.tactic_id_for_phase(tactic_id)
        return [
            self._by_id[technique_id]
            for technique_id in self._by_tactic.get(resolved_tactic_id, [])
            if technique_id in self._by_id
        ]

    def by_platform(self, platform: str) -> List[TechniqueOrSub]:
        return [
            self._by_id[technique_id]
            for technique_id in self._by_platform.get(platform.lower(), [])
            if technique_id in self._by_id
        ]

    def get_subtechniques_of(
        self, technique_id: str, domain: Domain | None = None
    ) -> List[SubTechnique]:
        resolved_id = self.resolve_attack_id(technique_id)
        domains = [domain] if domain is not None else list(Domain)
        subtechnique_ids = []
        for candidate_domain in domains:
            subtechnique_ids.extend(
                self._subtechniques_by_parent.get((candidate_domain, resolved_id), [])
            )
        return [
            self._by_domain_id[(candidate_domain, subtechnique_id)]
            for candidate_domain in domains
            for subtechnique_id in self._subtechniques_by_parent.get(
                (candidate_domain, resolved_id), []
            )
            if isinstance(self._by_domain_id.get((candidate_domain, subtechnique_id)), SubTechnique)
        ]

    def search(self, keyword: str) -> List[TechniqueOrSub]:
        keyword_lower = keyword.lower()
        return [
            technique
            for technique in self._by_id.values()
            if keyword_lower in technique.name.lower()
            or keyword_lower in technique.description.lower()
        ]

    def count_techniques(self, domain: Optional[Domain] = None) -> int:
        return sum(
            1
            for technique in self._by_domain_id.values()
            if not technique.is_subtechnique and (domain is None or technique.domain == domain)
        )

    def count_subtechniques(self, domain: Optional[Domain] = None) -> int:
        return sum(
            1
            for technique in self._by_domain_id.values()
            if technique.is_subtechnique and (domain is None or technique.domain == domain)
        )
